<script lang="ts">
 import GamepadDiagnostics from '../input/GamepadDiagnostics.svelte';
 import InputHint from '../input/InputHint.svelte';
 import {onMount} from 'svelte';
 import {audioPreferences} from '../audio/audioPreferences';
 import {displayPreferences} from './displayPreferences';
 import {createExitMotion} from '../motion/exitMotion.svelte';
 import HudWaves from '../hud/HudWaves.svelte';
 import SettingsIcon from './SettingsIcon.svelte';
 let {onClose,chapterTitle,subtitle='',chapterNumber='01'}:{onClose:()=>void;chapterTitle?:string;subtitle?:string;chapterNumber?:string}=$props();
 const exit=createExitMotion(320);
 const categories=[{id:'display',label:'顯示',en:'DISPLAY'},{id:'audio',label:'音效',en:'AUDIO'},{id:'gameplay',label:'遊戲',en:'GAMEPLAY'},{id:'language',label:'語言',en:'LANGUAGE'},{id:'controls',label:'操作',en:'CONTROLS'},{id:'interface',label:'介面',en:'INTERFACE'},{id:'accessibility',label:'輔助功能',en:'ACCESSIBILITY'},{id:'other',label:'其他',en:'OTHER'}];
 const channels=[{key:'master',label:'整體音量',en:'MASTER',description:'控制所有聲音的整體音量。調低後，背景音樂、音效與環境音會一起降低。'},{key:'music',label:'背景音樂',en:'MUSIC',description:'調整主選單與遊戲中的背景音樂，不影響環境音和操作音效。'},{key:'sfx',label:'音效',en:'SOUND EFFECTS',description:'調整攻擊、腳步與遊戲事件的音效音量。'},{key:'ambience',label:'環境音',en:'AMBIENCE',description:'調整風聲、水聲等場景環境音，保留旅途中的空間感。'}] as const;
 const help={mode:{title:'顯示模式',text:'全螢幕會隱藏瀏覽器邊框，讓畫面填滿螢幕。按 Esc 也能離開全螢幕。'},scale:{title:'渲染比例',text:'調整 3D 場景的內部解析度。降低比例可減少繪圖負擔；介面文字仍保持清晰。'},brightness:{title:'亮度',text:'調整 3D 場景曝光。100 為場景原始亮度，較低適合明亮環境，較高可看清暗處。'},contrast:{title:'對比',text:'調整 3D 場景明暗差異。100 保留原始美術設定。'},bloom:{title:'泛光效果',text:'在天空、反光與發光物體的高亮處加入柔和光暈。關閉可減少後製負擔。'},shadows:{title:'場景陰影',text:'顯示角色與建築的動態投影。關閉可減少部分繪圖負擔。'},samples:{title:'抗鋸齒',text:'以多重取樣平滑模型與建築邊緣。4× 的邊緣最細緻，較低設定可減少顯示負擔。'},muted:{title:'靜音',text:'暫時關閉所有聲音，保留各項音量設定。'}};
 type Help={title:string;text:string};
 let category=$state('display'),info=$state<Help>(help.mode),fullscreen=$state(false),fullscreenAvailable=$state(false),busy=$state(false),message=$state('');
 let root:HTMLDivElement;
 const active=$derived(categories.find(c=>c.id===category)!);
 const ready=$derived(category==='display'||category==='audio');
 function selectCategory(id:string){category=id;message='';info=id==='display'?help.mode:id==='audio'?{title:channels[0].label,text:channels[0].description}:id==='controls'?{title:'三種操作方式',text:'依最後使用的裝置切換提示。手把確認為下方鍵、返回為右方鍵；LB / RB 可依序選取所有選項。切換畫面後請先放開按鈕與搖桿。'}:{title:categories.find(c=>c.id===id)!.label,text:'這個分類正在準備中，後續會在這裡提供更多調整選項。'};}
 function reset(){if(!ready||exit.leaving)return;if(category==='display')displayPreferences.reset();else audioPreferences.reset();message='已恢復此分類的預設值。';}
 async function setFullscreen(next:boolean){
  if(busy||next===fullscreen)return;busy=true;message='';
  try{if(next)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}
  catch{message='無法切換全螢幕，請確認瀏覽器是否允許。';}
  finally{fullscreen=!!document.fullscreenElement;busy=false;}
 }
 onMount(()=>{const sync=()=>{fullscreen=!!document.fullscreenElement;fullscreenAvailable=!!document.fullscreenEnabled;};sync();document.addEventListener('fullscreenchange',sync);root.querySelector<HTMLElement>('[data-initial]')?.focus();return()=>document.removeEventListener('fullscreenchange',sync);});
 function keys(event:KeyboardEvent){
  if(event.defaultPrevented||event.ctrlKey||event.altKey||event.metaKey)return;
  if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(!event.repeat)exit.run(onClose);return;}
  if(exit.leaving)return;
  if(event.key.toLowerCase()==='f'&&!event.repeat){event.preventDefault();reset();}
  if(event.key==='Tab'){
   const items=[...root.querySelectorAll<HTMLElement>('button:not([disabled]),input,select')];const index=items.indexOf(document.activeElement as HTMLElement);
   event.preventDefault();items[(index+(event.shiftKey?items.length-1:1)+items.length)%items.length]?.focus();
  }
 }
 function navKeys(event:KeyboardEvent,index:number){if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();event.stopPropagation();const buttons=root.querySelectorAll<HTMLButtonElement>('.category');const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:buttons.length-1))%buttons.length;buttons[next]?.focus();}
</script>
<svelte:window onkeydown={keys}/>
<div class="settings-screen" class:leaving={exit.leaving} role="dialog" aria-modal="true" aria-label="遊戲設定" tabindex="-1" onkeydown={event=>{keys(event);event.stopPropagation();}} inert={exit.leaving} bind:this={root}>
 <div class="veil" aria-hidden="true"></div><div class="edge-frame" aria-hidden="true"></div>
 <div class="brand"><img src="/title/project-rondo-logo-v2.png" alt="PROJECT RONDO"/><small>BEYOND THE FAMILIAR SKY.</small></div>
 {#if chapterTitle}<div class="chapter"><p>CHAPTER <b>{chapterNumber}</b> ／</p><h2>{chapterTitle}</h2><small>{subtitle}</small></div>{:else}<div class="chapter menu-context"><p>PROJECT RONDO</p><h2>YOUR JOURNEY, YOUR WAY.</h2></div>{/if}
 <div class="layout">
  <aside class="rail">
   <header class="page-title"><span aria-hidden="true">✦</span><div><h1>SETTINGS</h1><p>設定 <i></i></p></div></header>
   <nav aria-label="設定分類">{#each categories as item,index}<button class="category" class:selected={category===item.id} aria-current={category===item.id?'page':undefined} data-initial={index===0?'':undefined} onclick={()=>selectCategory(item.id)} onkeydown={event=>navKeys(event,index)}><span class="icon"><SettingsIcon kind={item.id}/></span><span>{item.label}<small>{item.en}</small></span>{#if item.id!=='display'&&item.id!=='audio'&&item.id!=='controls'}<em>準備中</em>{:else}<b aria-hidden="true">›</b>{/if}</button>{/each}</nav>
   <button class="back" data-ui-sound="back" onclick={()=>exit.run(onClose)}><span>←</span><span>返回<small>BACK</small></span></button>
  </aside>
  <section class="settings-panel" aria-label={active.label+'設定'}>
   <header class="panel-heading"><SettingsIcon kind={category}/><h2>{active.label}設定 <small>{active.en}</small></h2></header>
   <p class="intro">{category==='display'?'依照你的螢幕與效能，調整旅途的畫面。':category==='audio'?'讓旋律、風聲與每一步，保持剛好的距離。':category==='controls'?'鍵鼠、標準配置控制器與觸控，共用相同的遊戲操作。':'更多設定，將隨旅途一起展開。'}</p>
   <div class="rows" data-input-scroll>
   {#if category==='display'}
    <div class="row" role="group" aria-label="顯示模式設定" class:highlight={info.title===help.mode.title} onpointerenter={()=>info=help.mode}>
     <span>顯示模式</span><div class="segments" role="group" aria-label="顯示模式"><button aria-pressed={!fullscreen} disabled={busy} onfocus={()=>info=help.mode} onclick={()=>setFullscreen(false)}>視窗</button><button aria-pressed={fullscreen} disabled={!fullscreenAvailable||busy} onfocus={()=>info=help.mode} onclick={()=>setFullscreen(true)}>全螢幕</button></div>
    </div>
    <label class="row" onpointerenter={()=>info=help.scale}><span>渲染比例</span><select aria-label="渲染比例" value={String($displayPreferences.renderScale)} onfocus={()=>info=help.scale} onchange={e=>displayPreferences.set('renderScale',Number(e.currentTarget.value))}><option value="1">100% · 原生</option><option value="0.75">75% · 平衡</option><option value="0.5">50% · 效能</option></select></label>
    {#each ['brightness','contrast'] as key}{@const setting=key as 'brightness'|'contrast'}
     <label class="row" onpointerenter={()=>info=help[setting]}><span>{help[setting].title}</span><div class="slider"><span class="small-icon" aria-hidden="true">{setting==='brightness'?'☼':'◐'}</span><input aria-label={help[setting].title} type="range" min="50" max="150" step="1" value={$displayPreferences[setting]} style={`--fill:${$displayPreferences[setting]-50}%`} onfocus={()=>info=help[setting]} oninput={e=>displayPreferences.set(setting,Number(e.currentTarget.value))}/><output>{$displayPreferences[setting]}</output></div></label>
    {/each}
    {#each ['bloom','shadows'] as key}{@const setting=key as 'bloom'|'shadows'}<div class="row" role="group" aria-label={help[setting].title+'設定'} onpointerenter={()=>info=help[setting]}><span>{help[setting].title}</span><div class="segments" role="group" aria-label={help[setting].title}>{#each [false,true] as value}<button aria-pressed={$displayPreferences[setting]===value} onfocus={()=>info=help[setting]} onclick={()=>displayPreferences.set(setting,value)}>{value?'開啟':'關閉'}</button>{/each}</div></div>{/each}
    <label class="row" onpointerenter={()=>info=help.samples}><span>抗鋸齒</span><select aria-label="抗鋸齒" value={String($displayPreferences.samples)} onfocus={()=>info=help.samples} onchange={e=>displayPreferences.set('samples',Number(e.currentTarget.value) as 1|2|4)}><option value="1">關閉</option><option value="2">MSAA 2×</option><option value="4">MSAA 4×</option></select></label>
    <p class="panel-note">畫質設定會在回到遊戲後的下一個畫面生效。{#if !fullscreenAvailable}<br/>目前環境未提供全螢幕切換。{/if}</p>
   {:else if category==='audio'}
    {#each channels as channel}<label class="row audio-row" onpointerenter={()=>info={title:channel.label,text:channel.description}}><span>{channel.label}<small>{channel.en}</small></span><div class="slider"><input type="range" min="0" max="100" step="1" aria-label={channel.label} value={Math.round($audioPreferences[channel.key]*100)} style={`--fill:${$audioPreferences[channel.key]*100}%`} onfocus={()=>info={title:channel.label,text:channel.description}} oninput={e=>audioPreferences.setLevel(channel.key,Number(e.currentTarget.value)/100)}/><output>{Math.round($audioPreferences[channel.key]*100)}</output></div></label>{/each}
    <div class="row" role="group" aria-label="靜音設定" onpointerenter={()=>info=help.muted}><span>靜音</span><div class="segments" role="group" aria-label="靜音">{#each [false,true] as value}<button aria-pressed={$audioPreferences.muted===value} onfocus={()=>info=help.muted} onclick={()=>audioPreferences.setMuted(value)}>{value?'開啟':'關閉'}</button>{/each}</div></div>
    <p class="panel-note">音量會即時套用。各音軌會依照遊戲內容播放。</p>
   {:else if category==='controls'}
    <div class="control-guide"><table><thead><tr><th>操作</th><th>鍵盤／滑鼠</th><th>控制器</th><th>觸控</th></tr></thead><tbody>
    {#each [['移動','WASD','左搖桿','左側搖桿'],['視角','滑鼠（點畫面捕捉）','右搖桿','右側滑動'],['跳躍／二段跳','Space','A / ×','跳躍鍵'],['揮劍／空中 Homing','J / 滑鼠左鍵','X / □','揮劍鍵'],['互動','E','X / □（靠近對象）','互動鍵'],['對話推進','Enter / 點擊對話框','X / □','點擊對話框'],['步行','Shift','LB / L1 或輕推','按住步行'],['地圖','M','Y / △','地圖圖示'],['暫停','Esc','Menu / Options','暫停鍵'],['選取／確認','方向鍵 / Tab / Enter','十字鍵 / LB RB / A','點選'],['返回','Esc','B / ○','返回按鈕'],['地圖移動／縮放','拖曳／滾輪','右搖桿／LT RT','拖曳／＋ −'],['回顧捲動','滾輪','右搖桿','滑動']] as row}<tr>{#each row as cell}<td>{cell}</td>{/each}</tr>{/each}
    </tbody></table></div><p class="panel-note">A / B / X / Y 對應 Xbox；× / ○ / □ / △ 對應 PlayStation。2D 關卡使用固定視角。此版提供預設配置，暫不提供自訂改鍵。</p>
   <GamepadDiagnostics/>
   {:else}<div class="coming"><SettingsIcon kind={category}/><h3>準備中</h3><p>此分類的設定尚未開放。</p><button onclick={()=>selectCategory('display')}>返回顯示設定</button></div>{/if}
   </div>
   <p class="save-note" role="status">{message||'設定自動儲存於此裝置。'}</p>
  </section>
  <aside class="details" aria-label="設定說明">
   <div class="help-card"><span class="corner" aria-hidden="true">✧</span><h3>{info.title}</h3><p>{info.text}</p>
    {#if category==='display'}<div class="display-preview"><img src="/title/white-palace-city-v1.png" alt="白色王城畫面示意" style={`filter:brightness(${$displayPreferences.brightness/100}) contrast(${$displayPreferences.contrast/100})`}/><span>WHITE PALACE · 白色王城</span></div><small class="preview-note">亮度與對比示意 · 實際效果以遊戲畫面為準</small>
    {:else if category==='audio'}<div class="sound-visual" class:muted={$audioPreferences.muted} aria-hidden="true">{#each [20,36,57,80,45,65,92,56,40,76,52,28,46,65,33,17] as height}<i style={`height:${height}%;opacity:${$audioPreferences.muted?.2:.3+$audioPreferences.master*.7}`}></i>{/each}</div><small class="preview-note">聲音設定 · AUDIO MIX</small>{/if}
   </div>
   {#if ready}<div class="status-card"><span>✧</span><div>隨你的步調，繼續旅程。<small>{category==='display'?'DISPLAY PREFERENCES':'AUDIO PREFERENCES'}</small></div></div>{/if}
  </aside>
 </div>
 <div class="waves" aria-hidden="true"><HudWaves edges={false}/></div>
 <footer>{#if ready}<button onclick={reset}><kbd><InputHint label="F"/></kbd> 恢復預設</button><span class="automatic">即時儲存</span>{/if}<button data-ui-sound="back" onclick={()=>exit.run(onClose)}><kbd><InputHint label="Esc"/></kbd> 返回</button></footer>
</div>
<style>
 .rows{min-height:0;flex:1;overflow:auto;overscroll-behavior:contain;padding:0 10px;margin:0 -10px;scrollbar-width:thin}.panel-heading,.intro,.save-note{flex-shrink:0}
