 .edge-frame{position:fixed;inset:0 1.7%;border-inline:1px solid #a8ccff30;pointer-events:none;z-index:-1}.edge-frame:before,.edge-frame:after{content:'✦';position:absolute;top:19%;left:-5px;color:#d6eaff;font-size:10px}.edge-frame:after{left:auto;right:-5px;top:67%}
 .brand{position:absolute;left:2.8%;top:3%;width:156px}.brand img{width:100%;filter:brightness(0) invert(1)}.brand small{font-size:8px;letter-spacing:.2em;white-space:nowrap;display:block;margin-top:6px}
 .chapter{position:absolute;right:4%;top:2.5%;text-align:right}.chapter p{font-size:11px;letter-spacing:.3em;margin:0}.chapter b{font:36px Georgia,serif;color:white;letter-spacing:.08em}.chapter h2{font-size:18px;font-weight:400;letter-spacing:.16em;margin:5px 0}.chapter small{font-size:11px;opacity:.7}.menu-context{top:4%}.menu-context h2{font-size:10px;letter-spacing:.22em;opacity:.65;margin-top:10px}
 .layout{display:grid;grid-template-columns:minmax(210px,21%) minmax(380px,1fr) minmax(235px,29%);gap:2.5cqw;height:100%;min-height:0;box-sizing:border-box;padding:14cqh 3.3cqw 115px}
 .rail{padding-top:2cqh}.page-title{display:flex;align-items:center;gap:20px;margin-bottom:30px}.page-title>span{font:65px Georgia,serif;color:#e1eeff;text-shadow:0 0 15px #4a84ff}.page-title h1{font:400 clamp(23px,2cqw,38px) Georgia,serif;letter-spacing:.2em;margin:0}.page-title p{font-size:12px;letter-spacing:.25em;margin:7px 0 0;display:flex;align-items:center;gap:12px}.page-title i{width:90px;height:1px;background:linear-gradient(90deg,#c5dcff80,transparent)}
 nav{display:grid;gap:8px}button,select{font:inherit;color:inherit;cursor:pointer}button{border:0;background:transparent}button:focus-visible,select:focus-visible,input:focus-visible{outline:1px solid #e5f3ff;outline-offset:4px}
 .category{position:relative;display:flex;align-items:center;gap:18px;min-height:53px;width:100%;padding:5px 15px 5px 9px;text-align:left;color:#bbcce4;isolation:isolate;font-size:16px;letter-spacing:.12em}.category:before{content:'';position:absolute;inset:0;clip-path:polygon(14px 0,calc(100% - 24px) 0,100% 50%,calc(100% - 24px) 100%,14px 100%,0 50%);z-index:-1;opacity:0;background:linear-gradient(90deg,#447af16b,#12223c88);border-block:1px solid #83b6ff;transition:opacity .2s}.category:hover:before,.category.selected:before{opacity:1}.category.selected{color:#fff;text-shadow:0 0 9px #76a9ff}.category .icon{width:34px;height:34px;padding:3px;flex:none}.category.selected .icon{background:#3972e180;outline:1px solid #a4d0ff;box-shadow:0 0 15px #427eff88;transform:rotate(45deg)}.category.selected .icon :global(svg){transform:rotate(-45deg)}:global(.category .icon svg){width:100%;height:100%}
 .category:focus-visible{outline:none}.category:focus-visible>span:nth-child(2){text-decoration:underline;text-underline-offset:5px}
