 .settings-panel{position:relative;align-self:stretch;display:flex;flex-direction:column;min-width:0;box-sizing:border-box;background:linear-gradient(130deg,#10213ae8,#142a49bd);border:1px solid #9bbffc68;box-shadow:inset 0 0 30px #5485bf0b;min-height:0;padding:0 24px 18px;clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px)}
 .panel-heading{display:flex;align-items:center;gap:18px;border-bottom:1px solid #a7c9ff59;padding:17px 0}.panel-heading :global(svg){width:28px;height:28px;flex:none}.panel-heading h2{font-size:20px;font-weight:400;letter-spacing:.1em;margin:0}.panel-heading small{font-size:9px;letter-spacing:.2em;margin-left:15px;color:#a9c2e4}.intro{font-size:11px;line-height:1.7;color:#a9bfde;margin:15px 0 18px}.row{position:relative;display:grid;grid-template-columns:1fr minmax(150px,53%);align-items:center;gap:18px;min-height:48px;border-bottom:1px solid #a4c6ff23;font-size:14px;letter-spacing:.06em}.row:focus-within,.row:hover,.row.highlight{background:linear-gradient(90deg,#3273e72b,transparent)}.row:focus-within:before{content:'';position:absolute;left:-9px;top:7px;bottom:7px;width:2px;background:#c9e7ff;box-shadow:0 0 8px #438bff}.row small{display:block;font-size:8px;color:#8ea9ce;letter-spacing:.14em;margin-top:5px}.audio-row{min-height:67px}
